-- Studio文件归属增量；仅追加，不改历史文件迁移。
IF COL_LENGTH(N'dbo.system_file_upload_session',N'owner_context_json') IS NULL ALTER TABLE dbo.system_file_upload_session ADD owner_context_json nvarchar(max) NULL;
IF OBJECT_ID(N'dbo.file_owned_reference',N'U') IS NULL
BEGIN
CREATE TABLE dbo.file_owned_reference (
    tenant_n_id nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
    reference_n_id nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
    file_n_id nvarchar(128) COLLATE Latin1_General_100_BIN2 NULL,
    owner_service nvarchar(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    owner_kind nvarchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL,
    owner_n_id nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
    operation_key nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
    status nvarchar(16) COLLATE Latin1_General_100_BIN2 NOT NULL,
    version bigint NOT NULL,
    created_on datetimeoffset(7) NOT NULL,
    expires_on datetimeoffset(7) NULL,
    released_on datetimeoffset(7) NULL,
    retention_until datetimeoffset(7) NULL,
    legal_hold bit NOT NULL,
    hold_reason nvarchar(512) NULL,
    last_updated_on datetimeoffset(7) NOT NULL,
    PRIMARY KEY (tenant_n_id,reference_n_id),
    UNIQUE (tenant_n_id,owner_service,operation_key),
    CHECK (status IN ('Pending','Active','Released') AND version>=0)
);
END;
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.file_owned_reference') AND name=N'ix_owned_file_status') CREATE INDEX ix_owned_file_status ON dbo.file_owned_reference (tenant_n_id,file_n_id,status);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.file_owned_reference') AND name=N'ix_owned_owner') CREATE INDEX ix_owned_owner ON dbo.file_owned_reference (tenant_n_id,owner_service,owner_kind,owner_n_id,reference_n_id);
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=0 AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'文件业务所有权引用；Pending与Active均保护内容，保全限制释放。',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'tenant_n_id','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'已验证租户标识；与所有者及文件一致',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'tenant_n_id';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'reference_n_id','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'服务器生成的业务引用键',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'reference_n_id';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'file_n_id','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'提交后绑定的不可变文件标识，准备阶段为空',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'file_n_id';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'owner_service','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'受信所属服务，首期platform-studio',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'owner_service';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'owner_kind','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'报告产物、预览、工作簿或Studio资产所有权种类',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'owner_kind';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'owner_n_id','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'所属业务对象稳定标识',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'owner_n_id';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'operation_key','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'同租户和所属服务唯一的准备幂等键',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'operation_key';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'status','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'Pending、Active或Released；未知扫描不激活',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'status';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'version','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'乐观并发版本，从0开始',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'version';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'created_on','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'首次准备UTC时刻',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'created_on';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'expires_on','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'Pending最早可回收时刻，不表示旧执行已停止',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'expires_on';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'released_on','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'确认解除业务引用的UTC时刻',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'released_on';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'retention_until','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'此UTC时刻前禁止释放',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'retention_until';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'legal_hold','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'法律保全标记，启用时禁止释放',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'legal_hold';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'hold_reason','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'保全理由，启用保全时必填',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'hold_reason';
IF NOT EXISTS (SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID(N'dbo.file_owned_reference') AND minor_id=COLUMNPROPERTY(OBJECT_ID(N'dbo.file_owned_reference'),N'last_updated_on','ColumnId') AND name=N'MS_Description') EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=N'最后一次受控状态推进的UTC时刻',@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=N'file_owned_reference',@level2type=N'COLUMN',@level2name=N'last_updated_on';
